def fila_a_fila(d):
    def segmento(f):
        if f["precio"] >= 600 and f["accommodates"] >= 7:
            return "lujo grupos"
        if f["precio"] >= 600:
            return "lujo"
        if f["accommodates"] >= 7:
            return "grupos"
        return "estandar"
    return d.apply(segmento, axis=1)

def por_columnas(d):
